package es.planidroid.app.ui
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.Alignment
import androidx.compose.ui.unit.dp
import androidx.compose.ui.window.Dialog
import androidx.compose.ui.window.DialogProperties
import es.planidroid.app.domain.*
import java.time.*

@Composable fun AgendaEditor(tasks:List<Task>,sessions:List<Session>,close:()->Unit,accept:(List<Session>,List<Session>)->Unit,external:List<Interval> = emptyList()){
    val eligible=tasks.filter{it.status !in listOf(Status.DONE,Status.ARCHIVED,Status.BLOCKED)&&TaskConstraints.unmet(it,tasks).isEmpty()}
    var picked by remember{mutableStateOf(eligible.filter{it.minutes>0||it.phases.any{p->p.minutes>0}}.map{it.id}.toSet())}
    var end by remember{mutableStateOf(LocalDate.now().plusDays(7).toString())};var from by remember{mutableStateOf("09:00")};var until by remember{mutableStateOf("19:00")};var max by remember{mutableStateOf("60")};var margin by remember{mutableStateOf("0")};var exceptions by remember{mutableStateOf("")};var advanced by remember{mutableStateOf(false)};var replan by remember{mutableStateOf(false)};var days by remember{mutableStateOf(DayOfWeek.entries.filter{it!=DayOfWeek.SUNDAY}.toSet())};var proposal by remember{mutableStateOf<AgendaProposal?>(null)};var replacing by remember{mutableStateOf(emptyList<Session>())};var error by remember{mutableStateOf("")};fun reset(){proposal=null;error="";replacing=emptyList()}
    val replacements=if(replan)sessions.filter{it.taskId in picked&&!it.done&&it.start>System.currentTimeMillis()}else emptyList();val kept=sessions.filterNot{it in replacements}
    LaunchedEffect(tasks,sessions,external){reset()}
    Dialog(onDismissRequest=close,properties=DialogProperties(usePlatformDefaultWidth=false)){Surface(Modifier.fillMaxSize()){LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
        item{Section("Planificar mi agenda","Distribuye sesiones sin solapamientos. No se modifican sesiones realizadas ni dependencias pendientes.");DateField(end,{end=it;reset()},"Último día",false);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Column(Modifier.weight(1f)){Field(from,{from=it;reset()},"Desde HH:mm")};Column(Modifier.weight(1f)){Field(until,{until=it;reset()},"Hasta HH:mm")}};TextButton(onClick={advanced=!advanced}){Text(if(advanced)"Ocultar opciones" else "Más opciones")};if(advanced){Field(max,{max=it;reset()},"Máximo de sesión (min)");Field(margin,{margin=it;reset()},"Margen antes de fecha límite (días)");Field(exceptions,{exceptions=it;reset()},"Días excluidos AAAA-MM-DD, separados por coma")};DayOfWeek.entries.chunked(4).forEach{r->Row(horizontalArrangement=Arrangement.spacedBy(5.dp)){r.forEach{d->FilterChip(d in days,{days=if(d in days)days-d else days+d;reset()},label={Text(listOf("L","M","X","J","V","S","D")[d.value-1])})}}};Row(verticalAlignment=Alignment.CenterVertically){Switch(replan,{replan=it;reset()});Text(" Reorganizar sesiones futuras de las tareas seleccionadas")};Text("${tasks.size-eligible.size} tareas excluidas por estado o dependencias")}
        items(eligible,key={it.id}){t->val remaining=TaskConstraints.remaining(t,kept);GlassCard(tint=categoryColor(t.category)){Row(verticalAlignment=Alignment.CenterVertically){Checkbox(t.id in picked,{v->picked=if(v)picked+t.id else picked-t.id;reset()},enabled=remaining>0||t.id in picked);Column(Modifier.weight(1f)){Text(t.title,style=MaterialTheme.typography.titleMedium);Text("$remaining min sin reservar")}}}}
        item{Button(enabled=picked.isNotEmpty(),modifier=Modifier.fillMaxWidth(),onClick={runCatching{
            val last=LocalDate.parse(end);val buffer=margin.toLong();require(buffer in 0..30);val zone=ZoneId.systemDefault();val excluded=exceptions.split(',').map{it.trim()}.filter{it.isNotBlank()}.map{LocalDate.parse(it)}.map{Interval(it.atStartOfDay(zone).toInstant().toEpochMilli(),it.plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli())};val inputs=eligible.filter{it.id in picked}.map{t->AgendaInput(t.id,t.title,TaskConstraints.remaining(t,kept),t.due.takeIf{it.isNotBlank()}?.let{LocalDate.parse(it).minusDays(buffer)}?:last,t.priority.ordinal,t.phases.filterNot{it.done}.map{p->p.id to (p.minutes-maxOf(p.actualMinutes,kept.filter{s->s.taskId==t.id&&s.phaseId==p.id&&s.done}.sumOf{s->((s.end-s.start)/60000).toInt()})-kept.filter{s->s.taskId==t.id&&s.phaseId==p.id&&!s.done}.sumOf{s->((s.end-s.start)/60000).toInt()}).coerceAtLeast(0)},t.startDate.takeIf{it.isNotBlank()}?.let{LocalDate.parse(it)})};AgendaPlanner.plan(inputs,LocalDate.now(),last,days,LocalTime.parse(from),LocalTime.parse(until),max.toInt(),kept.map{Interval(it.start,it.end)}+external+excluded)
        }.onSuccess{proposal=it;replacing=replacements;error=""}.onFailure{error="Revisa el periodo, horas, días excluidos y duración.";proposal=null}}){Text("Calcular propuesta")};if(error.isNotBlank())Text(error,color=MaterialTheme.colorScheme.error)}
        proposal?.let{p->item{GlassCard(tint=if(p.deficits.isEmpty())Mint else Peach){Text(if(p.deficits.isEmpty())"Plan viable" else "No cabe todo",style=MaterialTheme.typography.headlineSmall);Text("${p.blocks.size} sesiones propuestas · ${p.blocks.sumOf{(it.end-it.start)/60000}} min");if(replacing.isNotEmpty())Text("Se sustituirán ${replacing.size} sesiones futuras (${replacing.sumOf{(it.end-it.start)/60000}} min). Las demás se conservan.");p.deficits.forEach{Text("${it.title}: faltan ${it.minutes} min")}}};if(replacing.isNotEmpty()){item{Text("Antes",style=MaterialTheme.typography.titleMedium)};items(replacing,key={"old-${it.id}"}){b->Text("${sessionDate(b.start)} · ${time(b.start)} – ${time(b.end)} · ${tasks.find{it.id==b.taskId}?.title.orEmpty()}")};item{Text("Después",style=MaterialTheme.typography.titleMedium)}};items(p.blocks){b->GlassCard{Text("${sessionDate(b.start)} · ${time(b.start)} – ${time(b.end)}",style=MaterialTheme.typography.labelLarge);Text(tasks.find{it.id==b.taskId}?.title.orEmpty(),style=MaterialTheme.typography.titleMedium);tasks.find{it.id==b.taskId}?.phases?.find{it.id==b.phaseId}?.let{Text(it.title)}}};item{Button(enabled=p.blocks.isNotEmpty(),modifier=Modifier.fillMaxWidth(),onClick={accept(p.blocks.map{Session(taskId=it.taskId,phaseId=it.phaseId,start=it.start,end=it.end)},replacing)}){Text(if(p.deficits.isEmpty())"Aceptar planificación" else "Aceptar plan parcial")}}};item{TextButton(onClick=close){Text("Cancelar")}}
    }}}
}
